# 에필로그 새 문장 번역 6: 열나흘 사건(2차분 뒤쪽)
TR = {}
def T(en, en_m, ja1, ja2, ja3): return [(en, ja1), (en, ja2), (en_m, ja3)]
def E_(p, d): TR.update({p + '.' + i: v for i, v in d.items()})
E_('a_body', {
'b0': ("{N} stood before the mirror for a long time. There was a bruise where they had bumped yesterday. A wound that does not vanish seemed a marvel to them.", "{N}が鏡の前に長く立っていた。昨日ぶつけたところに痣ができていた。消えない傷が不思議らしかった。"),
'b0@sage': ("{N} was studying the bruise on their arm and writing something down. They were recording, day by day, the order in which its color changed.", "{N}が腕の痣を見ながら何かを書きつけていた。色の変わっていく順を、毎日記録しているところだと言った。"),
'b1': ("An incarnated body tires, hungers, and feels the cold. Each time {N} discovered one of these, they came to tell you.", "受肉した体は疲れ、腹が減り、寒さを感じた。{N}はそのひとつひとつを見つけるたびに、あなたに知らせに来た。"),
'b1@sage': ("An incarnated body tires, hungers, and feels the cold. {N} had known all of it. They had not known how different knowing is from undergoing.", "受肉した体は疲れ、腹が減り、寒さを感じた。{N}はすべて知っていた。知ることと味わうことがこれほど違うとは知らなかったと言った。"),
'b2': ("{N} had their fingers on their own wrist. There is a pulse, they said. Not mana, but blood.", "{N}が自分の手首に指を当てていた。脈が打っていると言った。魔力ではなく、血が。"),
'b2@sage': ("{N} had their fingers on their own wrist and their eyes on the clock. It was funny, they said, to get from their own body exactly the number they had read in a book.", "{N}が自分の手首に指を当て、時計を見ていた。本で読んだ数字がそのまま自分の体から出てくるのが可笑しいと言った。"),
'care.t': ("Teach them to look after it", "体の労わり方を教える"),
'care.r0': ("Sleep, food, washing. {N} wrote it all down. Like a manual of tactics.", "眠ること、食べること、洗うこと。{N}は書き留めた。戦術教本のように。"),
'care.r0@sage': ("Sleep, food, washing. {N} said they knew all that. It took three days for them to admit that knowing and keeping to it are different matters.", "眠ること、食べること、洗うこと。{N}は全部知っていると言った。知ることと守ることは別の問題だと、三日で認めた。"),
'care.r1': T("“It takes a great deal of tending. Living, I mean.”", "{N} pressed the bruise, winced, and then smiled a little.", "「手のかかるものだな。生きるというのは」", "「手のかかるものですね。生きるというのは」", "{N}が痣を押してみて顔をしかめ、少し笑った。"),
'care.r2': ("From that day {N} kept three mealtimes a day. They never once broke it.", "その日から{N}は一日三度の食事時を守った。一度も破らなかった。"),
'laugh.t': ("Laugh together", "一緒に笑う"),
'laugh.r0': ("The two of you laughed over a single bruise for a long time. That winter, this was someone who did not laugh even when an arm came off.", "痣ひとつを前に、二人でしばらく笑った。あの冬には、腕が落ちても笑わなかった人だった。"),
'laugh.r1': T("“It hurts. …I never thought pain would be so welcome.”", "{N} showed off the bruise as if proud of it.", "「痛い。……痛みがこれほど嬉しいとは思わなかった」", "「痛いです。……痛みがこれほど嬉しいとは思いませんでした」", "{N}が痣のところを自慢するように見せた。"),
'laugh.r2': ("That day {N} dipped a hand in cold water on purpose, and held a hot cup. They could feel all of it, they said.", "その日、{N}はわざと冷たい水に手を浸し、熱いカップを握ってみた。全部感じると言った。"),
'laugh.r2@sage': ("That day {N} held cold water and a hot cup by turns. An experiment, they said. Their face was not the face of someone experimenting.", "その日、{N}は冷たい水と熱いカップを交互に握ってみた。実験だと言った。顔は実験する者の顔ではなかった。"),
})
E_('a_hunger', {
'b0': ("At the table {N} hesitated, then said it. They were hungry. Saying so seemed to take courage.", "{N}が食卓の前でためらってから言った。腹が減ったと。そう言うのに勇気が要ったらしい。"),
'b0@sage': ("At the table {N} said that an empty stomach clouds the judgment. After a long pause they added: in short, they were hungry.", "{N}が食卓の前で言った。腹が空くと判断が鈍るものだと。しばらくして付け加えた。要するに、腹が減ったのだと。"),
'b1': ("In the dead of night you heard the fridge door open. {N} stood in its light with the face of one caught.", "真夜中、冷蔵庫の扉を開ける音がした。{N}が灯りの前に立って、見つかった顔をした。"),
'b1@cook': ("In the dead of night there were sounds from the kitchen. {N} was making a late snack from leftovers. Two plates were out.", "真夜中、台所から音がした。{N}が残り物で夜食を作っていた。皿が二枚出ていた。"),
'b2': ("A body that runs on meals, not mana. {N} still marveled at growing hungry three times a day.", "魔力ではなく飯で動く体。{N}は一日に三度腹が減ることを、まだ不思議がっていた。"),
'b2@sage': ("A body that runs on meals, not mana. {N} timed the intervals of their hunger for a few days and found it rather dull: just as the books said.", "魔力ではなく飯で動く体。{N}は腹の減る間隔を何日か計ってみて、本に書いてあるとおりだと少し拍子抜けしていた。"),
'make.t': ("Make them a late snack", "夜食を作ってあげる"),
'make.r0': ("The two of you ate noodles in the middle of the night. Your faces would be puffy tomorrow, and nobody cared.", "二人で真夜中に麺を食べた。明日は顔がむくむだろうが、誰も気にしなかった。"),
'make.r0@cook': ("When you took out a pot, {N} quietly came beside you and turned down the flame. In the end the two of you ate noodles {N} had made.", "あなたが鍋を出すと、{N}がそっと隣に来て火を弱めた。結局、{N}の作った麺を二人で食べた。"),
'make.r1': T("“I never knew a meal asked for could taste this good.”", "{N} emptied the bowl and put their hands together. Thanks for the meal.", "「頼んで得る飯がこれほど旨いとはな」", "「お願いしていただくご飯がこんなに美味しいとは思いませんでした」", "{N}が器を空にして手を合わせた。ごちそうさまという挨拶だった。"),
'make.r2': ("{N} drank even the broth. And said they would do the dishes.", "{N}は汁まで飲み干した。そして皿洗いは自分がすると言った。"),
'show.t': ("Show them the kitchen", "台所の使い方を教える"),
'show.r0': ("From the next day there was a note on the fridge. ‘Eaten: two eggs.’ {N} was honest.", "翌日から冷蔵庫に書き置きが貼られた。『食べた物：卵二つ』。{N}は正直だった。"),
'show.r0@cook': ("From the next day there was a note on the fridge. ‘Out of: eggs, scallions.’ {N} had taken on the shopping list too.", "翌日から冷蔵庫に書き置きが貼られた。『切れた物：卵、葱』。{N}は買い物の一覧まで引き受けた。"),
'show.r1': ("The first thing {N} cooked alone was a little burnt. They ate it all the same. A stomach filled by their own hand.", "{N}が初めて一人で作った物は少し焦げた。それでも最後まで食べた。自分の手で満たした腹だった。"),
'show.r1@cook': ("From the next day the kitchen had a new master. Every seasoning jar had moved, and it was easier to use than before.", "翌日から台所の主が替わった。調味料の容器の場所がすべて変わっていて、前より使いやすかった。"),
'show.r1@sage': ("The first thing {N} cooked alone was a little burnt. The theory was perfect, they said. The fire simply had not read the theory.", "{N}が初めて一人で作った物は少し焦げた。理論は完璧だったと言った。火が理論を読まなかっただけだと。"),
'show.r2': T("“To provide one's own food. That is as it should be.”", "{N} held up the pot and nodded. It meant they could manage alone now.", "「自分の食い扶持は自分で用意する。当然のことだ」", "「自分の食べる物は自分で用意する。当然のことです」", "{N}が鍋を持ち上げてみせて頷いた。もう一人でできるという意味だった。"),
})
E_('a_cut', {
'b0': ("A short cry from the kitchen. {N} had cut a finger. It bled. In spirit form it would have been a wound that scattered and returned. No longer.", "台所で短い声がした。{N}が指を切った。血が出た。霊体であれば、散って戻れば済む傷だった。今はそうはいかない。"),
'b0@sage': ("A short cry from the kitchen. {N} had cut a finger. {N} calmly raised the hand above the heart. Their expression was not calm.", "台所で短い声がした。{N}が指を切った。{N}は落ち着いて手を心臓より高く上げた。表情は落ち着いていなかった。"),
'b1': ("{N} cut a hand on paper. Cut by blades more times than they could count, they said, but never before by paper.", "{N}が紙で手を切った。刃で斬られたことは数えきれないが、紙で切ったのは初めてだと言った。"),
'b2': ("Blood beaded at {N}'s fingertip. {N} did not wipe it but watched. They had never looked at their own blood this long, they said.", "{N}の指先に血が玉になった。{N}はそれを拭かずに見ていた。自分の血をこんなに長く見たことはないと言った。"),
'b2@sage': ("Blood beaded at {N}'s fingertip. {N} was timing how long it took to clot. You fetched the tissue first.", "{N}の指先に血が玉になった。{N}は固まるまでの時間を計っていた。あなたが先にティッシュを持ってきた。"),
'band.t': ("Put a bandage on it", "絆創膏を貼ってあげる"),
'band.r0': ("One bandage. {N} kept it on for days, like a medal.", "絆創膏一枚だった。{N}はそれを勲章のように、何日も剥がさなかった。"),
'band.r1': T("“No one ever tended a wound this small for me.”", "{N} held up the bandaged finger and looked at it for a long while.", "「こんな小さな傷を誰かが手当てしてくれたことはなかった」", "「こんな小さな傷を誰かが手当てしてくださったことはありませんでした」", "{N}が絆創膏を貼った指を立ててみせて、しばらく眺めていた。"),
'band.r2': ("The cut healed in three days. {N} wrote on the calendar that it takes three days.", "傷は三日後に塞がった。三日かかるということを、{N}は暦に書いておいた。"),
'band.r2@sage': ("The cut healed in three days. A day later than expected, {N} said, and blamed the diet.", "傷は三日後に塞がった。{N}は予想より一日遅かったと言って、食事のせいにした。"),
'self.t': ("Have them do it themselves", "自分でやらせる"),
'self.r0': ("{N} learned how to use the first-aid kit. Next time it might be your turn, they said, so they ought to know.", "{N}は救急箱の使い方を覚えた。次はあなたの番かもしれないから、知っておくべきだと言った。"),
'self.r0@sage': ("{N} opened the first-aid kit and rearranged its contents. The order was wrong, they said. Next time it might be your turn.", "{N}は救急箱を開けて、中を並べ直した。置く順が間違っていると言った。次はあなたの番かもしれないから。"),
'self.r1': ("The bandage went on crooked. {N} looked satisfied.", "曲がって貼られた絆創膏だった。{N}は満足そうな顔をしていた。"),
'self.r2': T("“A body that takes time to mend. I must use it sparingly.”", "{N} clenched and opened the injured hand, and this time took up the knife with care.", "「治るのに時間のかかる体か。大事に使わねばな」", "「治るのに時間のかかる体ですね。大事に使わないと」", "{N}が怪我をした手を握って開き、今度は慎重に包丁を握った。"),
})
E_('a_call', {
'b0': ("A call came from your family. How have you been lately? Beside you, {N} held their breath.", "家族から電話が来た。最近どうしているのかと。隣で{N}が息を殺した。"),
'b1': ("An old friend asked what had happened — you could not be reached all that winter.", "古い友人が尋ねた。あの冬の間ずっと連絡がつかなかったが、何があったのかと。"),
'b2': ("The voice on the line said your voice had changed. Had you met someone?", "電話の向こうの声が言った。声が変わったと。誰かできたのかと。"),
'half.t': ("Tell half of it", "半分だけ話す"),
'half.r0': ("You said only that there is someone you live with now. Even that much delighted them for a long while.", "一緒に暮らす人ができたとだけ言った。向こうはそれだけでも長いこと喜んだ。"),
'half.r1': ("When the call ended {N} asked how you had described them. Hearing the answer, they were silent for a long time.", "通話が終わると{N}が尋ねた。自分のことを何と言ったのかと。答えを聞いて、しばらく黙っていた。"),
'half.r2': T("“I must go and pay my respects someday. Courtesy must be observed.”", "{N} made as if to straighten their collar. It meant they would get ready to pay a visit.", "「いつか挨拶に行かねばな。礼は尽くすべきだ」", "「いつかご挨拶に伺わないといけませんね。礼は尽くさないと」", "{N}が襟を正す仕草をした。挨拶に行く支度をするという意味だった。"),
'none.t': ("Say nothing's new", "特に何もないと言う"),
'none.r0': ("Nothing's new had never been so great a lie. Nor so great a truth.", "特に何もないという言葉が、これほど大きな嘘だったことはない。そしてこれほど本当だったこともない。"),
'none.r1': ("You hung up and met {N}'s eyes. You both smiled a little. The something new was sitting right beside you.", "電話を切って{N}と目が合った。二人とも少し笑った。何かあった張本人が隣に座っていた。"),
'none.r2': ("{N} said nothing. Whether they minded not being introduced, you could not tell. Dinner was a little quiet.", "{N}は何も言わなかった。紹介されなかったのが寂しいのかどうかは分からなかった。夕食は少し静かだった。"),
})
E_('a_work', {
'b0': ("You had to return to ordinary life. As you left in the morning, {N} followed you to the door.", "あなたは日常に戻らなければならなかった。朝、家を出るとき、{N}が玄関までついてきた。"),
'b1': ("For the first time since the war you had to leave {N} for a day. In fourteen days you had never once been apart.", "戦争のあと初めて、{N}を置いて一日出かけなければならなかった。十四日の間、離れたことがなかった。"),
'b2': ("{N} asked whether this was truly a place they need not follow you to. Sending you off unguarded was not something they were used to.", "{N}が尋ねた。自分がついて行かなくていい場所で間違いないのかと。護衛なしで送り出すのは慣れていないと言った。"),
'go.t': ("Say you'll be back", "行ってくると言う"),
'go.r0': ("When you returned, the house had changed a little. The creaking door was silent, and the shoes were in order.", "戻ると、家が少し変わっていた。軋んでいた扉が静かになり、靴が揃っていた。"),
'go.r1': T("“Go. I will keep this place.”", "{N} stood in the entryway with a hand raised. They did not lower it until the door closed.", "「行ってこい。ここは私が守る」", "「行ってらっしゃい。ここは私が守ります」", "{N}が玄関に立って手を上げた。扉が閉まるまで下ろさなかった。"),
'go.r2': ("No word came from {N} all day. When you got back, dinner was on the table.", "一日中、{N}から連絡はなかった。戻ると、夕食が用意されていた。"),
'lunch.t': ("Drop by at lunchtime", "昼に少し寄る"),
'lunch.r0': ("At noon you opened the door to find {N} sitting right in the entryway. It looked as though they had been there the whole time.", "昼に扉を開けると、{N}が玄関のすぐ前に座っていた。ずっとそこにいたようだった。"),
'lunch.r1': ("Thirty minutes. Those thirty minutes changed {N}'s whole afternoon, you were told later.", "三十分だった。その三十分で{N}の午後が変わったと、あとで聞いた。"),
'lunch.r2': T("“Come to check on me? …Not bad.”", "{N} got up with a startled face, and at once went to put the kettle on.", "「確かめに来たのか。……悪くないな」", "「確かめに来てくださったのですか。……嬉しいです」", "{N}が驚いた顔で立ち上がり、すぐに湯を沸かしに行った。"),
})
E_('a_board', {
'b0': ("An old shogi board and a chessboard came out of the closet. The look in {N}'s eyes changed.", "押し入れから古い将棋盤とチェス盤が出てきた。{N}の目つきが変わった。"),
'b1': ("{N} picked up a piece and turned it this way and that. They were intrigued to hear there was a war without bloodshed.", "{N}が駒をひとつ手に取って、あちこち眺めた。血の流れない戦があると聞いて、興味を示した。"),
'b1@now': ("{N} picked up a piece and blew off the dust. They knew the rules, they said. They had simply had no one to play.", "{N}が駒をひとつ手に取って、埃を吹いた。ルールは知っていると言った。指す相手がいなかっただけだと。"),
'b1@modern': ("{N} picked up a piece and blew off the dust. They knew the rules, they said. They had simply had no one to play.", "{N}が駒をひとつ手に取って、埃を吹いた。ルールは知っていると言った。指す相手がいなかっただけだと。"),
'b2': ("A rainy evening with nothing to do. A board was set between you.", "雨の夕方、することがなかった。二人の間に盤が置かれた。"),
'play.t': ("Play without going easy", "手加減せずに指す"),
'play.r0': ("You won the first game. And the second. From the third, {N}'s moves changed. Dawn came.", "一局目はあなたが勝った。二局目も。三局目から{N}の手が変わった。夜が明けた。"),
'play.r1': T("“One more. That was not a loss. That was a lesson.”", "{N} set the pieces back up and tapped the board. It meant: one more game.", "「もう一局。今のは負けたのではない。学んだのだ」", "「もう一局です。今のは負けたのではありません。学んだのです」", "{N}が駒を並べ直して盤を叩いた。もう一局という意味だった。"),
'play.r2': ("{N} enjoyed themselves even in defeat. It was a fight in which no one dies for losing.", "{N}は負けても楽しそうだった。負けても誰も死なない戦いだった。"),
'teach.t': ("Teach them slowly", "ゆっくり教える"),
'teach.r0': ("Having learned all the rules, {N} held one piece for a long time. A pawn. The piece that can become anything if it reaches the end.", "ルールをすべて覚えた{N}が、駒をひとつ長く握っていた。歩だった。最後まで進めば何にでもなれる駒。"),
'teach.r1': ("When you offered to take a move back, {N} shook their head. Not taking back was their way, they said.", "あなたが一手待ってやると、{N}は首を振った。待ったをしないのが自分の流儀だと言った。"),
'teach.r2': T("“A good game. Even if the king is taken, he can be set up again tomorrow.”", "{N} picked up the fallen king and stood it back up. That seemed to please them.", "「良い遊びだ。王が取られても、明日また立てられるのだから」", "「良い遊びですね。王が取られても、明日また立てられますから」", "{N}が倒れた王を拾って、立て直した。それが気に入ったらしい。"),
})
E_('a_song', {
'b0': ("Doing the dishes, you heard a low song behind you. {N} was humming without knowing it. A tune you had never heard.", "皿を洗っていると、後ろから低い歌が聞こえた。{N}が知らず知らず口ずさんでいた。初めて聞く節だった。"),
'b1': ("{N} was humming something by the window. When you turned, they stopped. Something they used to hear in life, they said.", "{N}が窓辺で何かを口ずさんでいた。あなたが振り向くとやめた。生前に聞いていたものだと言った。"),
'b2': ("A song came on the radio. {N} stopped walking and listened to the end.", "ラジオから歌が流れた。{N}が足を止めて、最後まで聞いた。"),
'ask.t': ("Ask what song it is", "何の歌か訊く"),
'ask.r0': ("An old song. They had forgotten about half the words, they said. The half that remained {N} sang for you slowly.", "古い歌だった。歌詞は半分ほど忘れたと言った。残った半分を、{N}がゆっくり歌ってくれた。"),
'ask.r1': T("“Someone used to sing it to me. The face is dim; only the tune is left.”", "{N} hummed the tune once more and pointed at their ear. It remains here, that meant.", "「誰かが歌ってくれていたものだ。顔はぼやけて、節だけが残った」", "「誰かが歌ってくれていたものです。顔はぼやけて、節だけが残りました」", "{N}が節をもう一度口ずさみ、自分の耳を指した。ここに残っているという意味だった。"),
'ask.r2': ("There were now two people in the world who knew that song.", "その歌を知る者は、今や世界に二人になった。"),
'sing.t': ("Sing along", "一緒に歌う"),
'sing.r0': ("You were off-key. {N} could not hold back a laugh. Still, you sang it through together.", "音が外れた。{N}は笑いを堪えられなかった。それでも最後まで一緒に歌った。"),
'sing.r1': ("You taught them a song you knew. The next day {N} hummed it while folding the laundry.", "あなたの知っている歌をひとつ教えた。翌日、{N}がそれを口ずさみながら洗濯物を畳んでいた。"),
'sing.r2': T("“Sung by two, it becomes a different song. This one is better.”", "{N} kept time with a hand. Time set to your voice.", "「二人で歌うと別の歌になるな。こちらの方がいい」", "「二人で歌うと別の歌になりますね。こちらの方がいいです」", "{N}が手で拍子を取った。あなたの声に合わせた拍子だった。"),
})
E_('a_stars', {
'b0': ("You went up to the roof. {N} looked up at the sky and said nothing. There were too few stars.", "屋上に上がった。{N}は空を見上げて黙っていた。星が少なすぎた。"),
'b1': ("A clear night. {N} leaned on the roof railing counting stars. They were soon counted.", "晴れた夜だった。{N}が屋上の手すりにもたれて星を数えていた。すぐに数え終わった。"),
'b2': ("{N} was searching the night sky for something. The star that showed the way in their day, they said.", "{N}が夜空に何かを探していた。自分の時代に道を教えてくれた星だと言った。"),
'b2@now': ("{N} was looking up at the night sky. The sky they once looked up at with someone as a child was like this, they said. Who it was has gone dim.", "{N}が夜空を見上げていた。幼い頃、誰かと見上げた空がこんなふうだった気がすると言った。誰だったのかはぼやけていると。"),
'find.t': ("Look for it together", "一緒に探す"),
'find.r0': ("After a long while you found one. A star barely visible between the city lights. {N} kept pointing at it for a long time.", "しばらくして、ひとつ見つけた。街の灯りの間にかろうじて見える星だった。{N}は長くそれを指していた。"),
'find.r1': T("“The ground grew bright, so the sky grew dark. Not a bad bargain.”", "{N} pointed at the sky, then at the lights below. As if the stars had come down to earth.", "「地上が明るくなって、空が暗くなったか。悪い取引ではない」", "「地上が明るくなって、空が暗くなったのですね。悪い取引ではありません」", "{N}が空を指し、それから下の灯りを指した。星が地上に降りてきたとでも言うように。"),
'find.r1@now': T("“Few stars, many lights. It means that many people are living.”", "{N} pointed at the sky, then at the lights below. As if to say that one was the better sight.", "「星は少なくても灯りは多い。それだけ人が生きているということだ」", "「星は少なくても灯りは多いです。それだけ人が生きているということですね」", "{N}が空を指し、それから下の灯りを指した。あちらの方が見応えがあるとでも言うように。"),
'find.r2': ("You heard about the constellations. The names {N} knew were different from the ones you knew. They were the same stars.", "星座の話を聞いた。{N}の知る名前は、あなたの知る名前と違っていた。同じ星だった。"),
'find.r2@now': ("You named the constellations. The ones {N} knew and the ones you knew were the same. You had grown up under the same sky.", "星座の名前を挙げてみた。{N}の知るものと、あなたの知るものは同じだった。同じ空の下で育ったのだ。"),
'city.t': ("Look at the night view", "夜景を眺める"),
'city.r0': ("Windows shone in place of stars. Behind each of those lights is a person. That is what the two of you guarded that winter.", "星の代わりに窓が光っていた。あの灯りのひとつひとつに人がいる。あの冬に二人で守ったものだった。"),
'city.r1': ("{N} looked down at the city for a long time. No one knows who guarded this night. They liked that, they said.", "{N}は長いこと街を見下ろしていた。この夜を誰が守ったのか、誰も知らない。それが気に入っていると言った。"),
'city.r2': T("“Those lights did not go out. That is enough.”", "{N} reached a hand toward the lights, and clenched and opened it.", "「あの灯りは消えなかった。それでいい」", "「あの灯りは消えませんでした。それでいいのです」", "{N}が灯りの方へ手を伸ばし、握って、開いた。"),
})
E_('a_wash', {
'b0': ("You hung out the laundry. {N}'s clothes hung side by side with yours. Nothing remarkable, and yet your eyes kept going to it.", "洗濯物を干した。{N}の服があなたの服の隣に並んで掛かった。何でもない光景なのに、目が行った。"),
'b1': ("{N} stood holding a wet shirt. They did not know how to shake it out. Shown how, they shook it with all their might and water flew everywhere.", "{N}が濡れた服を持って立っていた。はたき方が分からないからだった。教えると全力ではたいて、水が四方に飛んだ。"),
'b2': ("The sun was good on the balcony. {N} sat among the laundry. They liked the smell of it drying, they said.", "ベランダに陽がよく当たっていた。{N}が洗濯物の間に座っていた。乾いていく匂いがいいと言った。"),
'fold.t': ("Teach them to fold", "畳み方を教える"),
'fold.r0': ("What {N} folded had crisp corners. Hands that used to fold field tents, they said.", "{N}の畳んだ服は角が立っていた。陣幕を畳んでいた手だと言った。"),
'fold.r0@now': ("What {N} folded had crisp corners. The hands of someone who had kept house alone for a long time.", "{N}の畳んだ服は角が立っていた。長く一人で家事をしてきた手だった。"),
'fold.r0@civil': ("The corners of what {N} folded did not line up. Only after folding it three times over were they satisfied.", "{N}の畳んだ服は角が合っていなかった。三度畳み直して、ようやく満足した。"),
'fold.r0@mage': ("The corners of what {N} folded did not line up. Only after folding it three times over were they satisfied.", "{N}の畳んだ服は角が合っていなかった。三度畳み直して、ようやく満足した。"),
'fold.r1': ("They refolded one towel five times. {N} does not know the meaning of roughly.", "タオル一枚を五度畳み直した。{N}は適当ということを知らない。"),
'fold.r2': T("“Easier than battle, and more endless than battle.”", "{N} looked at the pile of laundry, then up at the sky once.", "「戦より易しく、戦より終わりがないな」", "「戦より易しく、戦より終わりがないですね」", "{N}が積まれた洗濯物を見て、空を一度見上げた。"),
'sun.t': ("Bask in the sun together", "一緒に日向ぼっこをする"),
'sun.r0': ("The two of you sat among the laundry for an hour. You did nothing at all.", "二人で洗濯物の間に座って、一時間を過ごした。何もしなかった。"),
'sun.r1': ("{N} dozed off. You covered them with a towel dried in the sun.", "{N}がうとうとした。陽に乾いたタオルをかけてやった。"),
'sun.r2': ("The clothes swayed in the wind. {N} looked up at them as at banners. This time they were no one's battle standard.", "風に服が揺れた。{N}はそれを旗でも見るように見上げた。今度は誰の軍旗でもなかった。"),
})
